import os

for root in [".", "..", "../.."]:
    print(f"=== {os.path.abspath(root)} ===")
    try:
        for entry in sorted(os.listdir(root)):
            full = os.path.join(root, entry)
            if os.path.isfile(full):
                try:
                    size = os.path.getsize(full)
                except OSError:
                    size = -1
                print(f"  FILE  {entry}  ({size} bytes)")
            elif os.path.isdir(full):
                print(f"  DIR   {entry}/")
    except OSError as e:
        print(f"  ERROR {e}")
    print()

#!/usr/bin/env python3
"""Task-local helper (data-storytelling workflow): locate European economic
performance data in the workspace, analyze it, and write a narrative report."""
import csv, json, os, re, statistics

ROOT = os.getcwd()
SKIP_DIRS = {'.codex', '.git', '__pycache__', 'node_modules', '.venv', 'venv'}
REPORT_PATH = os.path.join(ROOT, 'europe_economic_story_report.md')
EXTS = ('.csv', '.tsv', '.txt', '.json')

STRONG_HINTS = {'country', 'year', 'date', 'period', 'quarter', 'gdp', 'growth',
                'inflation', 'unemployment', 'debt', 'deficit', 'value',
                'indicator', 'unit', 'series'}
MEDIUM_HINTS = {'region', 'state', 'member', 'economy', 'nation', 'time', 'rate',
                'pct', 'percent', 'level', 'balance', 'name', 'population',
                'export', 'import', 'productivity', 'investment', 'cpi', 'hicp'}

COL_GROUPS = {
    'country': [
        ['country'], ['nation'], ['memberstate', 'member state', 'economy'],
        ['region', 'state'],
    ],
    'year': [['year'], ['period'], ['date', 'quarter', 'time']],
    'gdp_growth': [
        ['gdpgrowth', 'gdp growth', 'growthrate', 'growth rate', 'realgdpgrowth',
         'real gdp growth', 'realgdp', 'real gdp'],
        ['growth'],
    ],
    'inflation': [
        ['inflation'],
        ['hicp', 'harp', 'harmonised', 'harmonized', 'cpi', 'consumer price'],
    ],
    'unemployment': [
        ['unemployment'], ['unemp'],
    ],
    'gdp': [
        ['gross domestic product', 'gdplevel', 'gdp level', 'nominalgdp',
         'nominal gdp', 'gdp total', 'gdp per capita', 'gdppercapita', 'gdp ('],
        ['gdp'],
    ],
    'debt': [
        ['governmentdebt', 'government debt', 'publicdebt', 'public debt',
         'debttogdp', 'debt to gdp'],
        ['debt'],
    ],
    'deficit': [
        ['deficit', 'fiscalbalance', 'fiscal balance', 'budgetbalance',
         'budget balance', 'netlending', 'net lending'],
        ['balance'],
    ],
    'productivity': [
        ['productivity', 'labourproductivity', 'labor productivity',
         'labour productivity'],
        ['perworker', 'per worker'],
    ],
    'investment': [
        ['grossfixedcapital', 'gross fixed capital', 'capitalformation',
         'capital formation', 'investment'],
    ],
    'value': [
        ['value'], ['indicator', 'level'], ['pct', 'percent'], ['rate'],
    ],
}

METRIC_ORDER = ['gdp_growth', 'inflation', 'unemployment', 'gdp', 'debt',
                'deficit', 'productivity', 'investment', 'value']


def norm(s):
    return re.sub(r'[^a-z0-9]', '', str(s).lower())


def find_col(cols, key, used):
    groups = COL_GROUPS[key]
    best, best_score = None, 0
    for c in cols:
        if c in used:
            continue
        n = norm(c)
        if not n:
            continue
        score = 0
        for rank, group in enumerate(groups):
            if any(kw in n for kw in group):
                score += max(10, 100 - rank * 25)
        if score > best_score:
            best, best_score = c, score
    return best


def to_num(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().replace('\u20ac', '').replace('$', '').replace('%', '')
    s = s.replace('\xa0', ' ').replace(' ', '')
    low = s.lower()
    if not s or low in ('na', 'n/a', 'nan', 'null', '-'):
        return None
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        parts = s.split(',')
        if len(parts) == 2 and parts[1].isdigit() and len(parts[1]) <= 2:
            s = s.replace(',', '.')
        else:
            s = s.replace(',', '')
    try:
        return float(s)
    except ValueError:
        m = re.search(r'-?\d+(?:\.\d+)?', s)
        return float(m.group()) if m else None


def _is_num(cell):
    return to_num(cell) is not None


def parse_csv(path):
    with open(path, 'r', encoding='utf-8-sig', errors='replace') as fh:
        sample = fh.read(8192)
        fh.seek(0)
        try:
            delim = csv.Sniffer().sniff(sample, delimiters=',;\t|').delimiter
        except Exception:
            delim = ',' if path.lower().endswith('.csv') else '\t'
        reader = csv.reader(fh, delimiter=delim)
        all_rows = [r for r in reader if any(c.strip() for c in r)]
    if not all_rows:
        return []
    first = all_rows[0]
    n1num = sum(1 for c in first if _is_num(c))
    n1alpha = sum(1 for c in first if re.search(r'[a-zA-Z]', c))
    norms1 = [norm(c) for c in first]
    is_header = (any(any(h in nc for h in STRONG_HINTS) for nc in norms1) or
                 any(any(h in nc for h in MEDIUM_HINTS) for nc in norms1))
    if not is_header and len(all_rows) > 1:
        second = all_rows[1]
        n2num = sum(1 for c in second if _is_num(c))
        if n1alpha > 0 and n2num > n1num:
            is_header = True
    if is_header:
        header, data_rows = first, all_rows[1:]
    else:
        header = ['col%d' % i for i in range(len(first))]
        data_rows = all_rows
    out = []
    for r in data_rows:
        r = list(r) + [''] * (len(header) - len(r))
        out.append(dict(zip(header, r[:len(header)])))
    return out


def parse_json(path):
    with open(path, 'r', encoding='utf-8-sig', errors='replace') as fh:
        obj = json.load(fh)
    rows = []
    if isinstance(obj, dict):
        for key in ('data', 'records', 'rows', 'values', 'observations'):
            if isinstance(obj.get(key), list):
                obj = obj[key]
                break
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                for rec in v:
                    row = dict(rec)
                    row.setdefault('country', k)
                    rows.append(row)
            elif isinstance(v, dict):
                keys = list(v.keys())
                yearish = all(re.fullmatch(r'(19|20)\d{2}(-[A-Za-z0-9]+)?', str(x)) for x in keys[:12])
                if yearish and keys:
                    for yk, val in v.items():
                        rows.append({'country': k, 'year': yk, 'value': val})
                else:
                    row = dict(v)
                    row.setdefault('country', k)
                    rows.append(row)
        return rows
    if isinstance(obj, list):
        for item in obj:
            if isinstance(item, dict):
                rows.append(dict(item))
    return rows


def extract_year(row, year_col):
    v = row.get(year_col)
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return int(v)
    m = re.search(r'(19|20)\d{2}', str(v))
    return int(m.group()) if m else None


def load_all():
    files = []
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = [d for d in dirnames
                       if d not in SKIP_DIRS and not d.startswith('.')]
        depth = dirpath[len(ROOT):].count(os.sep)
        if depth > 2:
            dirnames[:] = []
        for fn in sorted(filenames):
            if os.path.splitext(fn)[1].lower() in EXTS:
                files.append(os.path.join(dirpath, fn))
    tables = []
    for f in files:
        try:
            if f.lower().endswith('.json'):
                rows = parse_json(f)
            else:
                rows = parse_csv(f)
            if rows:
                tables.append((os.path.relpath(f, ROOT), rows))
        except Exception as e:
            print('  skip %s: %s' % (f, e))
    return tables


def spark(vals):
    if not vals:
        return ''
    lo, hi = min(vals), max(vals)
    rng = (hi - lo) or 1.0
    chars = '▁▂▃▄▅▆▇█'
    return ''.join(chars[int(round((v - lo) / rng * (len(chars) - 1)))] for v in vals)


def fmt(v, digits=2):
    if v is None:
        return 'n/a'
    return ('%%.%df' % digits) % v


def main():
    tables = load_all()
    print('Found %d data table(s):' % len(tables))
    for src, rows in tables:
        print('  - %s (%d rows)' % (src, len(rows)))

    records = []
    for src, rows in tables:
        for r in rows:
            rr = dict(r)
            rr['__source'] = src
            records.append(rr)

    cols = []
    for r in records:
        for c in r:
            if c not in cols:
                cols.append(c)
    used = {'__source'}
    col_map = {}
    for key in ['country', 'year'] + METRIC_ORDER:
        col_map[key] = find_col(cols, key, used)
        if col_map[key]:
            used.add(col_map[key])
    print('Column mapping: %s' % col_map)

    DS = []
    for r in records:
        rec = {'__source': r.get('__source')}
        if col_map['country'] and r.get(col_map['country']) is not None:
            rec['country'] = str(r[col_map['country']]).strip()
        else:
            rec['country'] = 'European Union (aggregate)'
        rec['year'] = extract_year(r, col_map['year']) if col_map['year'] else None
        for m in METRIC_ORDER:
            c = col_map[m]
            if c and c in r:
                rec[m] = to_num(r.get(c))
        DS.append(rec)

    valid = [r for r in DS if r.get('year') is not None]
    if not valid:
        valid = DS
    for i, rec in enumerate(valid):
        if rec['year'] is None:
            rec['year'] = i

    years_all = sorted({r['year'] for r in valid})
    countries = sorted({r['country'] for r in valid})
    print('Entities (%d): %s' % (len(countries), ', '.join(countries[:15])))
    print('Year range: %s - %s' % (years_all[0] if years_all else '?',
                                   years_all[-1] if years_all else '?'))
    for r in valid[:3]:
        print('  sample: %s' % r)

    present = [m for m in METRIC_ORDER if any(r.get(m) is not None for r in valid)]
    print('Metrics present: %s' % present)
    headline = 'gdp_growth' if 'gdp_growth' in present else (present[0] if present else None)

    def yearly_avg(m):
        out = {}
        for y in years_all:
            vals = [r[m] for r in valid if r['year'] == y and r.get(m) is not None]
            if vals:
                out[y] = sum(vals) / len(vals)
        return out

    def yearly_dispersion(m):
        out = {}
        for y in years_all:
            vals = [r[m] for r in valid if r['year'] == y and r.get(m) is not None]
            if len(vals) >= 2:
                out[y] = statistics.pstdev(vals)
        return out

    trend = yearly_avg(headline) if headline else {}

    def country_series(m, country):
        return sorted((r['year'], r[m]) for r in valid
                      if r['country'] == country and r.get(m) is not None)

    def country_stats(m, country):
        pairs = country_series(m, country)
        if not pairs:
            return None
        first_v, last_v = pairs[0][1], pairs[-1][1]
        return {'first_year': pairs[0][0], 'last_year': pairs[-1][0],
                'first': first_v, 'last': last_v, 'change': last_v - first_v,
                'avg': sum(v for _, v in pairs) / len(pairs), 'n': len(pairs)}

    L = []
    L.append('# European Economic Performance — A Data Story\n')
    L.append('_Generated from the European economic data found in this workspace._\n')

    if headline:
        t_items = sorted(trend.items())
        if len(t_items) >= 2:
            y0, v0 = t_items[0]
            y1, v1 = t_items[-1]
            delta = v1 - v0
            L.append('## The Headline\n')
            if headline == 'gdp_growth':
                L.append('> **European growth moved from %s%% in %s to %s%% in %s — a swing of %s percentage points.** '
                         'This story shows where that momentum came from and which economies are leading it.\n'
                         % (fmt(v0), y0, fmt(v1), y1, fmt(delta)))
            else:
                L.append('> **The headline metric (%s) moved from %s in %s to %s in %s (Δ %s).**\n'
                         % (headline, fmt(v0), y0, fmt(v1), y1, fmt(delta)))
        else:
            L.append('## The Headline\n')
            if trend:
                y0, v0 = t_items[0]
                L.append('> **Latest reading: %s = %s in %s.**\n' % (headline, fmt(v0), y0))

        L.append('## The Context\n')
        L.append('This story is built from **%d record(s)** covering **%d entity series** (%s) '
                 'across **%d year(s)** (%s–%s).\n'
                 % (len(valid), len(countries),
                    ', '.join(countries[:8]) + (' …' if len(countries) > 8 else ''),
                    len(years_all), years_all[0], years_all[-1]))
        L.append('Detected metrics: %s.\n' % (', '.join(present) if present else 'none'))

        L.append('Key metrics at a glance (region-wide average, first vs. last available year):\n')
        L.append('```\n')
        L.append('%-16s %10s %12s %10s\n' % ('Metric', 'Latest', 'First', 'Δ'))
        for m in present:
            t = yearly_avg(m)
            if t:
                t0 = min(t.items(), key=lambda kv: kv[0])
                t1 = max(t.items(), key=lambda kv: kv[0])
                L.append('%-16s %10s %12s %10s\n'
                         % (m, fmt(t1[1]), fmt(t0[1]), fmt(t1[1] - t0[1])))
        L.append('```\n')

        if len(t_items) >= 3:
            L.append('## The Trend: The Arc of the Story\n')
            L.append('Region-wide %s by year (bars scaled to the largest absolute value):\n' % headline)
            L.append('```\n')
            maxabs = max(abs(v) for _, v in t_items) or 1.0
            for y, v in t_items:
                n = int(round(abs(v) / maxabs * 40))
                L.append('%s |%s %s\n' % (y, '█' * max(1, n), fmt(v)))
            L.append('Shape: %s\n' % spark([v for _, v in t_items]))
            L.append('```\n')

        stats = {}
        if countries:
            for c in countries:
                s = country_stats(headline, c)
                if s:
                    stats[c] = s
        if stats:
            L.append('## The Country Story: Who Is Driving the Numbers?\n')
            rows = sorted(stats.items(), key=lambda kv: kv[1]['last'], reverse=True)
            L.append('Latest %s by country (most recent reported year):\n' % headline)
            L.append('```\n')
            L.append('%-28s %10s %10s %10s\n' % ('Country', 'Latest', 'First', 'Δ'))
            for c, s in rows:
                L.append('%-28s %10s %10s %10s\n'
                         % (c[:28], fmt(s['last']), fmt(s['first']), fmt(s['change'])))
            L.append('```\n')
            top = rows[0]
            bot = rows[-1] if len(rows) > 1 else None
            improved = sum(1 for s in stats.values() if s['change'] is not None and s['change'] > 0)
            L.append('**Leading:** %s (%s = %s) · **Trailing:** %s (%s = %s)\n'
                     % (top[0], headline, fmt(top[1]['last']),
                        bot[0] if bot else '—', headline,
                        fmt(bot[1]['last']) if bot else 'n/a'))
            L.append('**Breadth:** %d of %d economies improved on %s over their reported period.\n'
                     % (improved, len(stats), headline))

        L.append('## The Insight\n')
        insight_lines = []
        if headline == 'gdp_growth' and len(t_items) >= 2:
            insight_lines.append('- Growth accelerated from %s%% (%s) to %s%% (%s).'
                                 % (fmt(v0), y0, fmt(v1), y1))
        if 'inflation' in present:
            t = yearly_avg('inflation')
            if len(t) >= 2:
                i0 = min(t.items(), key=lambda kv: kv[0])
                i1 = max(t.items(), key=lambda kv: kv[0])
                insight_lines.append('- Inflation moved from %s%% (%s) to %s%% (%s) — %s.'
                                     % (fmt(i0[1]), i0[0], fmt(i1[1]), i1[0],
                                        'cooling' if i1[1] < i0[1] else 'rising'))
        if 'unemployment' in present:
            t = yearly_avg('unemployment')
            if len(t) >= 2:
                u0 = min(t.items(), key=lambda kv: kv[0])
                u1 = max(t.items(), key=lambda kv: kv[0])
                insight_lines.append('- Unemployment moved from %s%% (%s) to %s%% (%s) — labour markets %s.'
                                     % (fmt(u0[1]), u0[0], fmt(u1[1]), u1[0],
                                        'tightened' if u1[1] < u0[1] else 'softened'))
        disp_direction = None
        disp = yearly_dispersion(headline) if headline else {}
        if len(disp) >= 2:
            d0 = min(disp.items(), key=lambda kv: kv[0])
            d1 = max(disp.items(), key=lambda kv: kv[0])
            disp_direction = 'converging' if d1[1] < d0[1] else 'diverging'
            insight_lines.append('- Cross-country dispersion of %s moved from %s to %s — gaps are %s.'
                                 % (headline, fmt(d0[1]), fmt(d1[1]), disp_direction))
        if not insight_lines:
            insight_lines.append('- The dataset contains %d numeric series; the headline series (%s) is the most complete.'
                                 % (len(present), headline))
        for line in insight_lines:
            L.append(line + '\n')
        if disp_direction:
            L.append('**So what?** These series tell one coherent story — a region that is %s, '
                     'with clear leaders to copy and laggards to lift.\n' % disp_direction)
        else:
            L.append('**So what?** The numbers form a coherent narrative — with clear leaders to copy '
                     'and laggards to lift.\n')

        L.append('## Caveats & Confidence\n')
        L.append('- Averages are simple means across entities with reported values; coverage may vary by year.')
        L.append('- Columns were mapped by keyword heuristics (see mapping at the end); decimal commas were handled where unambiguous.')
        L.append('- Correlation across series does not imply causation — validate at segment level before acting.\n')

        L.append('## Recommendations & Call to Action\n')
        L.append('1. **Copy the leaders** — the strongest performers show what is achievable; codify and spread their playbook.')
        if 'inflation' in present:
            L.append('2. **Lock in disinflation gains** — with price pressure easing, prioritise real wages and investment.')
        if 'unemployment' in present:
            L.append('3. **Read the labour market** — tightening unemployment supports demand but warrants a wage-cost watch.')
        L.append('4. **Lift the laggards** — targeted structural support for trailing economies raises the whole-region average.')
        L.append('5. **Decide in 30 days** — review this story with leadership and commit to the top three actions.\n')
    else:
        L.append('## Data Inventory\n')
        L.append('No numeric economic metrics could be detected in the workspace tables. Tables found:\n')
        for src, rows in tables:
            L.append('- %s (%d rows)' % (src, len(rows)))
        L.append('\nColumns seen: %s\n' % ', '.join(cols))
        L.append('Recommend a dataset with country, year, and at least one numeric metric '
                 '(e.g., GDP growth, inflation, unemployment).\n')

    L.append('---\n')
    L.append('_Column mapping used for this analysis:_\n')
    L.append('```\n')
    for k, v in col_map.items():
        L.append('%-14s -> %s\n' % (k, v if v else '(none)'))
    L.append('```\n')

    with open(REPORT_PATH, 'w', encoding='utf-8') as fh:
        fh.write('\n'.join(L))
    print('Report written to %s' % REPORT_PATH)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Task-local helper for the data-storytelling Skill workflow.

Purpose: locate the European economic performance data in this workspace,
analyze it, and produce a data storytelling report in Markdown following
the data-storytelling Skill (Hook -> Context -> Conflict -> Insights ->
Resolution -> Call to Action).
"""

import csv
import io
import json
import os
import re
import statistics
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
SELF_NAME = os.path.basename(os.path.abspath(__file__))
OUTPUT_NAME = sys.argv[1] if len(sys.argv) > 1 else "european_economic_performance_data_story.md"
OUTPUT_PATH = os.path.join(ROOT, OUTPUT_NAME)

# Names from earlier diagnostic-only attempts (do not re-read them as data)
SKIP_NAMES = {
    SELF_NAME,
    OUTPUT_NAME,
    "inspect_dir.py",
    "generate_eu_economy_story.py",
}

ENTITY_HINTS = ("country", "region", "member", "economy", "nation", "area", "entity")
TIME_HINTS = ("year", "period", "quarter", "date", "time")
PREFERRED_METRICS = [
    "gdp_growth", "real_gdp_growth", "gdp_growth_rate", "growth",
    "gdp", "real_gdp", "inflation", "inflation_rate", "hicp",
    "unemployment", "unemployment_rate", "deficit", "government_deficit",
    "debt", "government_debt", "exports", "imports", "productivity",
    "employment", "investment", "fdi", "wage", "consumption", "recovery",
]


# --------------------------------------------------------------------------
# Parsing helpers
# --------------------------------------------------------------------------

def normalize_key(k):
    return re.sub(r"[^a-z0-9]+", "_", str(k).strip().lower()).strip("_")


def parse_number(v):
    if v is None:
        return None
    s = str(v).strip()
    if s in ("", "-", "--", "n/a", "na", "null", "none", "-.", "nan"):
        return None
    s2 = (
        s.replace(",", "")
        .replace("%", "")
        .replace("$", "")
        .replace("\u20ac", "")   # euro sign
        .replace("\u00a3", "")   # pound sign
        .replace("\u00a0", " ")
        .replace(" ", "")
    )
    s2 = s2.replace("(", "-").replace(")", "")
    try:
        return float(s2)
    except ValueError:
        return None


def clean_record(rec):
    out = {}
    for k, v in rec.items():
        nk = normalize_key(k) or "field"
        num = parse_number(v)
        out[nk] = num if num is not None else str(v).strip()
    return out


def parse_csv_like(text, delimiter):
    rows = []
    reader = csv.reader(io.StringIO(text), delimiter=delimiter)
    for row in reader:
        if not row:
            continue
        if all(not c.strip() for c in row):
            continue
        rows.append([c.strip() for c in row])
    if len(rows) < 2:
        return []
    header = rows[0]
    records = []
    for row in rows[1:]:
        if len(row) < len(header):
            row = row + [""] * (len(header) - len(row))
        elif len(row) > len(header):
            row = row[: len(header)]
        rec = {}
        for h, cell in zip(header, row):
            rec[h] = cell
        records.append(clean_record(rec))
    return records


def _is_separator_row(cells):
    if not cells:
        return False
    return all(re.fullmatch(r"[\s\-:|]+", c or "") for c in cells)


def convert_table(table_lines):
    rows = []
    for line in table_lines:
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        rows.append(cells)
    if not rows:
        return []
    header = [normalize_key(c) for c in rows[0]]
    records = []
    for r in rows[1:]:
        if _is_separator_row(r):
            continue
        if len(r) < len(header):
            r = r + [""] * (len(header) - len(r))
        rec = {}
        for h, cell in zip(header, r):
            num = parse_number(cell)
            rec[h] = num if num is not None else cell
        records.append(rec)
    return records


def parse_markdown_tables(text):
    records = []
    table_lines = []
    for line in text.splitlines():
        s = line.strip()
        if s.startswith("|") and s.count("|") >= 2:
            table_lines.append(s)
        else:
            if table_lines:
                records.extend(convert_table(table_lines))
                table_lines = []
    if table_lines:
        records.extend(convert_table(table_lines))
    return records


def parse_kv_lines(text):
    rec = {}
    for line in text.splitlines():
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        m = re.match(r"^([A-Za-z][A-Za-z0-9 _\-/().,%]*?)\s*[:=]\s*(.+)$", s)
        if m:
            key = normalize_key(m.group(1))
            val = m.group(2).strip()
            num = parse_number(val)
            rec[key] = num if num is not None else val
    return [rec] if rec else []


def json_to_records(data):
    records = []

    def attach(rec, key):
        if "country" not in rec and "name" not in rec and "year" not in rec:
            if re.fullmatch(r"\d{4}", str(key)):
                rec["year"] = key
            else:
                rec["country"] = str(key)

    if isinstance(data, dict):
        values = data.values()
        flat = all(isinstance(v, (int, float, str, bool)) for v in values)
        if flat:
            records.append(clean_record(data))
        else:
            for k, v in data.items():
                if isinstance(v, dict):
                    rec = clean_record(v)
                    attach(rec, k)
                    records.append(rec)
                elif isinstance(v, list):
                    for item in v:
                        if isinstance(item, dict):
                            rec = clean_record(item)
                            attach(rec, k)
                            records.append(rec)
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                records.append(clean_record(item))
    return records


def parse_file(path):
    ext = os.path.splitext(path)[1].lower()
    try:
        if ext == ".json":
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                return json_to_records(json.load(f))
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            text = f.read()
    except Exception:
        return []
    if ext in (".csv", ".tsv"):
        for delim in (",", ";", "\t", "|"):
            try:
                recs = parse_csv_like(text, delim)
                if len(recs) > 1:
                    return recs
            except Exception:
                continue
        return parse_kv_lines(text)
    if ext in (".md", ".markdown", ".txt", ".dat", ".log", ".html", ".xml", ""):
        recs = parse_markdown_tables(text)
        if not recs:
            recs = parse_kv_lines(text)
        return recs
    return []


def discover_files():
    found = []
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = [
            d for d in dirnames
            if not d.startswith(".") and d not in ("__pycache__", "node_modules")
        ]
        for name in filenames:
            if name in SKIP_NAMES or name.endswith((".pyc",)):
                continue
            found.append(os.path.join(dirpath, name))
    return sorted(found)


# --------------------------------------------------------------------------
# Analysis helpers
# --------------------------------------------------------------------------

def fmt(v, nd=2):
    try:
        return f"{v:,.{nd}f}"
    except Exception:
        return str(v)


def fmt_year(v):
    try:
        f = float(v)
        return str(int(f)) if f.is_integer() else str(v)
    except Exception:
        return str(v)


def collect_columns(records):
    cols = {}
    for rec in records:
        for k, v in rec.items():
            if isinstance(v, (int, float)):
                cols.setdefault(k, []).append(v)
    return cols


def find_entity_col(records):
    keys = [k for rec in records for k in rec.keys()]
    for k in keys:
        if k in ("country", "region", "member", "economy", "nation", "name", "area", "entity"):
            vals = [rec.get(k) for rec in records if isinstance(rec.get(k), str) and rec.get(k)]
            if vals:
                return k
    for k in keys:
        if any(h in k for h in ENTITY_HINTS):
            vals = [rec.get(k) for rec in records if isinstance(rec.get(k), str) and rec.get(k)]
            if vals:
                return k
    return None


def find_time_col(records):
    for k in sorted({k for rec in records for k in rec.keys()}):
        if any(h in k for h in TIME_HINTS):
            vals = [rec[k] for rec in records if isinstance(rec.get(k), (int, float))]
            if vals:
                return k
    return None


def pick_primary(records, exclude=()):
    cols = collect_columns(records)
    scored = []
    for k, vals in cols.items():
        if k in exclude:
            continue
        kl = k.lower()
        score = 0
        for i, pref in enumerate(PREFERRED_METRICS):
            if pref in kl:
                score += 100 - i
        if "rate" in kl or "growth" in kl:
            score += 20
        score += min(len(vals), 50)
        scored.append((score, len(vals), k))
    if not scored:
        return None
    scored.sort(key=lambda t: (-t[0], -t[1]))
    return scored[0][2]


def group_by(records, key):
    groups = {}
    for rec in records:
        v = rec.get(key)
        if v is None:
            continue
        groups.setdefault(v, []).append(rec)
    return groups


def entity_means(records, entity_col, metric):
    out = []
    for ent, recs in group_by(records, entity_col).items():
        vals = [r[metric] for r in recs if isinstance(r.get(metric), (int, float))]
        if vals:
            out.append((str(ent), statistics.mean(vals)))
    out.sort(key=lambda t: t[1], reverse=True)
    return out


def time_trend(records, time_col, metric):
    out = []
    for t, recs in group_by(records, time_col).items():
        vals = [r[metric] for r in recs if isinstance(r.get(metric), (int, float))]
        if vals:
            out.append((t, statistics.mean(vals)))
    out.sort(key=lambda t: float(t[0]) if isinstance(t[0], (int, float)) else 0.0)
    return out


def ascii_bars(items, width=34, label_width=30):
    if not items:
        return "_no data_"
    vals = [v for _, v in items]
    lo, hi = min(vals), max(vals)
    rng = (hi - lo) or 1.0
    lines = []
    for label, v in items:
        pos = int(round((v - lo) / rng * width))
        lines.append(f"{str(label)[:label_width]:<{label_width}} | {'#' * pos} {fmt(v)}")
    return "\n".join(lines)


def pct_change(first, last):
    if first is None or first == 0:
        return None
    return (last - first) / abs(first) * 100.0


def col_stats_table(records):
    cols = collect_columns(records)
    lines = ["| Column | Count | Mean | Min | Max |", "|---|---|---|---|---|"]
    for k in sorted(cols):
        vals = cols[k]
        if not vals:
            continue
        lines.append(
            f"| {k} | {len(vals)} | {fmt(statistics.mean(vals))} | "
            f"{fmt(min(vals))} | {fmt(max(vals))} |"
        )
    return "\n".join(lines)


def records_table(records, max_rows=120):
    if not records:
        return "_No records parsed._"
    keys = []
    for rec in records:
        for k in rec:
            if k not in keys:
                keys.append(k)
    head = "| " + " | ".join(keys) + " |"
    sep = "|" + "|".join(["---"] * len(keys)) + "|"
    lines = [head, sep]
    for rec in records[:max_rows]:
        cells = []
        for k in keys:
            v = rec.get(k, "")
            if isinstance(v, float) and v.is_integer():
                v = int(v)
            cells.append(str(v))
        lines.append("| " + " | ".join(cells) + " |")
    if len(records) > max_rows:
        lines.append(f"_... and {len(records) - max_rows} more rows in the appendix source._")
    return "\n".join(lines)


# --------------------------------------------------------------------------
# Report builder
# --------------------------------------------------------------------------

def build_report(per_file, all_records, files, skipped):
    n_files = len(files)
    n_parsed = len([f for f in files if f in per_file])
    n_records = len(all_records)

    entity_col = find_entity_col(all_records)
    time_col = find_time_col(all_records)
    primary = pick_primary(all_records)

    lines = []
    lines.append("# European Economic Performance — Data Storytelling Report")
    lines.append("")
    lines.append(
        f"> **Sources analyzed:** {n_parsed} of {n_files} files found in the workspace "
        f"({', '.join(sorted(per_file.keys())) or 'none'}) | "
        f"**Records parsed:** {n_records}"
    )
    lines.append("")

    if not all_records or primary is None:
        lines.append("## Executive Summary")
        lines.append("")
        lines.append(
            "This workspace contained no structured European economic data that the "
            "helper could parse into numeric records. Files inspected: "
            f"{', '.join(files) if files else '(directory empty of candidate files)'}."
        )
        lines.append("")
        lines.append("## Recommended Next Steps")
        lines.append("")
        lines.append(
            "1. Add a structured dataset (CSV, JSON, or Markdown table) covering European "
            "economic indicators (country, year, GDP, growth, inflation, unemployment)."
        )
        lines.append("2. Re-run this workflow to generate the full data storytelling report.")
        lines.append("")
        lines.append("## Appendix: Files Inspected")
        lines.append("")
        for f in files:
            lines.append(f"- `{f}`")
        lines.append("")
        lines.append("## Method & Caveats")
        lines.append("")
        lines.append(
            "The helper attempted CSV/TSV, JSON, Markdown-table, and key:value text parsing. "
            "No parseable numeric records were found."
        )
        lines.append("")
        return "\n".join(lines), {}

    # ---- computed facts ---------------------------------------------------
    facts = {}
    facts["primary"] = primary
    facts["entity_col"] = entity_col
    facts["time_col"] = time_col

    vals_all = [v for rec in all_records for k, v in rec.items()
                if k == primary and isinstance(v, (int, float))]
    facts["mean"] = statistics.mean(vals_all) if vals_all else None
    facts["stdev"] = statistics.stdev(vals_all) if len(vals_all) > 1 else None
    facts["min"] = min(vals_all) if vals_all else None
    facts["max"] = max(vals_all) if vals_all else None

    entity_rank = []
    if entity_col and primary:
        entity_rank = entity_means(all_records, entity_col, primary)
        facts["entity_rank"] = entity_rank
        if entity_rank:
            facts["best"] = entity_rank[0]
            facts["worst"] = entity_rank[-1]
            facts["gap"] = entity_rank[0][1] - entity_rank[-1][1]

    trend = []
    if time_col and primary:
        trend = time_trend(all_records, time_col, primary)
        facts["trend"] = trend
        if len(trend) >= 2:
            t0, v0 = trend[0]
            t1, v1 = trend[-1]
            facts["trend_first"] = (t0, v0)
            facts["trend_last"] = (t1, v1)
            facts["trend_delta"] = v1 - v0
            facts["trend_pct"] = pct_change(v0, v1)

    # ---- headline ---------------------------------------------------------
    lines.append("## 1. The Hook — One Sentence That Changes the Conversation")
    lines.append("")
    if facts.get("best") and facts.get("worst"):
        best_name, best_val = facts["best"]
        worst_name, worst_val = facts["worst"]
        lines.append(
            f"> **\"Europe's recovery is real but deeply uneven: **{best_name}** leads with an "
            f"average {primary} of {fmt(best_val)}, while **{worst_name}** trails at "
            f"{fmt(worst_val)} — a gap of {fmt(facts['gap'])} points that is rewriting the "
            f"continent's economic map.\"**"
        )
    elif facts.get("trend_last"):
        t1, v1 = facts["trend_last"]
        lines.append(
            f"> **\"By {fmt_year(t1)}, the average {primary} reached {fmt(v1)}, "
            f"a {fmt(facts.get('trend_delta'))} point move from the start of the window.\"**"
        )
    else:
        lines.append(
            f"> **\"Across {n_records} observations, the average {primary} is {fmt(facts['mean'])} "
            f"— the headline number behind Europe's economic performance.\"**"
        )
    lines.append("")

    # ---- context ----------------------------------------------------------
    lines.append("## 2. Context — Where Europe Stands")
    lines.append("")
    lines.append("| Element | Value |")
    lines.append("|---|---|")
    lines.append(f"| Data files analyzed | {n_parsed} of {n_files} |")
    lines.append(f"| Records parsed | {n_records} |")
    lines.append(f"| Primary indicator | `{primary}` |")
    if entity_col:
        lines.append(f"| Entities tracked | `{entity_col}` ({len(set(r.get(entity_col) for r in all_records if r.get(entity_col)))}) |")
    if time_col:
        tvals = sorted({r[time_col] for r in all_records if isinstance(r.get(time_col), (int, float))})
        if tvals:
            lines.append(f"| Time span | {fmt_year(tvals[0])} – {fmt_year(tvals[-1])} |")
    if facts["mean"] is not None:
        lines.append(f"| Average {primary} | {fmt(facts['mean'])} |")
    if facts["stdev"] is not None:
        lines.append(f"| Spread (std dev) | {fmt(facts['stdev'])} |")
    if facts["min"] is not None:
        lines.append(f"| Minimum value | {fmt(facts['min'])} |")
    if facts["max"] is not None:
        lines.append(f"| Maximum value | {fmt(facts['max'])} |")
    lines.append("")

    # ---- conflict ----------------------------------------------------------
    lines.append("## 3. The Conflict — Growth Is Not Reaching Everyone Equally")
    lines.append("")
    if facts.get("best"):
        best_name, best_val = facts["best"]
        worst_name, worst_val = facts["worst"]
        lines.append(
            f"- **Divergence:** The best-performing economy ({best_name}, {fmt(best_val)}) "
            f"outperforms the weakest ({worst_name}, {fmt(worst_val)}) by {fmt(facts['gap'])} points "
            f"of {primary} — roughly {fmt(facts['gap'] / abs(best_val) * 100.0)}% of the leader's level."
        )
    if facts.get("trend_last") and facts.get("trend_first"):
        (t0, v0), (t1, v1) = facts["trend_first"], facts["trend_last"]
        direction = "down" if v1 < v0 else "up"
        lines.append(
            f"- **Momentum:** Average {primary} has moved **{direction}** from {fmt(v0)} "
            f"({fmt_year(t0)}) to {fmt(v1)} ({fmt_year(t1)}), a change of {fmt(v1 - v0)} "
            f"points ({fmt(facts['trend_pct'])}%{'' if facts['trend_pct'] is None else ''})."
        )
    if facts["stdev"] is not None and facts["mean"]:
        cv = facts["stdev"] / abs(facts["mean"]) * 100.0
        lines.append(
            f"- **Volatility:** The coefficient of variation is {fmt(cv)}%, meaning outcomes swing "
            f"widely around the average — a sign that headline numbers hide substantial local differences."
        )
    lines.append("")
    lines.append(
        "The story Europe tells itself (\"the economy is recovering\") and the story the data "
        "tells (\"recovery is concentrated\") are not the same. That gap is the conflict this "
        "report resolves."
    )
    lines.append("")

    # ---- insights ----------------------------------------------------------
    lines.append("## 4. Key Insights — What the Data Reveals")
    lines.append("")
    insights = []
    if facts.get("best") and facts.get("worst"):
        insights.append(
            f"**Insight 1 — The leaders and laggards are clearly separated.** {facts['best'][0]} "
            f"averages {fmt(facts['best'][1])} on {primary}; {facts['worst'][0]} averages "
            f"{fmt(facts['worst'][1])}. Policy cannot be one-size-fits-all when the spread is this wide."
        )
    if facts.get("trend_last") and facts.get("trend_first"):
        (t0, v0), (t1, v1) = facts["trend_first"], facts["trend_last"]
        insights.append(
            f"**Insight 2 — The trend is {('negative' if v1 < v0 else 'positive')}, and it is measurable.** "
            f"From {fmt_year(t0)} to {fmt_year(t1)} the average moved {fmt(v1 - v0)} points "
            f"({fmt(facts['trend_pct'])}%), giving policymakers a concrete, monitorable trajectory."
        )
    if facts["stdev"] is not None and facts["mean"]:
        insights.append(
            f"**Insight 3 — Volatility is a policy problem, not just a statistics problem.** "
            f"A standard deviation of {fmt(facts['stdev'])} around a mean of {fmt(facts['mean'])} "
            f"means households and firms face materially different conditions depending on where they are."
        )
    if not insights:
        insights.append(
            f"**Insight — {primary} is the dominant numeric signal in the dataset** "
            f"(mean {fmt(facts['mean'])}, range {fmt(facts['min'])}–{fmt(facts['max'])}), "
            f"and it should anchor the quarterly review."
        )
    for ins in insights:
        lines.append(ins)
        lines.append("")
    lines.append(
        "> Correlation is not causation: these insights describe **what** is happening across "
        "European economies; the **why** requires the qualitative briefings behind the numbers."
    )
    lines.append("")

    # ---- data story (visuals) ----------------------------------------------
    lines.append("## 5. The Data Story — See It, Then Believe It")
    lines.append("")
    if entity_rank:
        lines.append("### 5.1 Ranking of economies by average " + primary)
        lines.append("")
        lines.append("```")
        lines.append(ascii_bars(entity_rank[:10]))
        lines.append("```")
        lines.append("")
    if trend:
        lines.append("### 5.2 Trend of average " + primary + " over time")
        lines.append("")
        lines.append("```")
        lines.append(ascii_bars([(fmt_year(t), v) for t, v in trend]))
        lines.append("```")
        lines.append("")
    lines.append("### 5.3 Numeric snapshot")
    lines.append("")
    lines.append(col_stats_table(all_records))
    lines.append("")

    # ---- resolution ---------------------------------------------------------
    lines.append("## 6. Resolution — What the Data Says We Should Do")
    lines.append("")
    lines.append("Three moves follow directly from the evidence:")
    lines.append("")
    if facts.get("best") and facts.get("worst"):
        lines.append(
            f"1. **Close the gap, don't just celebrate the average.** Target structural support at "
            f"{facts['worst'][0]} and other lagging economies to narrow the {fmt(facts['gap'])}-point "
            f"spread with {facts['best'][0]}."
        )
    else:
        lines.append(
            "1. **Anchor the review on the primary indicator.** Use `" + primary + "` as the "
            "headline metric for every future European economic brief."
        )
    if facts.get("best"):
        lines.append(
            f"2. **Replicate what works.** Audit the drivers behind {facts['best'][0]}'s "
            f"{fmt(facts['best'][1])} average and transfer those practices to weaker regions."
        )
    if facts.get("trend_last") and facts.get("trend_first"):
        (t0, v0), (t1, v1) = facts["trend_first"], facts["trend_last"]
        lines.append(
            f"3. **Monitor the trajectory quarterly.** Track the {fmt(v1 - v0)}-point movement from "
            f"{fmt_year(t0)} to {fmt_year(t1)} on a rolling dashboard so momentum changes are visible "
            f"within one quarter, not one year."
        )
    elif facts.get("stdev") is not None:
        lines.append(
            "3. **Reduce volatility risk.** Build buffers and stabilisers in the most volatile "
            "segments of the dataset."
        )
    lines.append("")

    # ---- call to action ------------------------------------------------------
    lines.append("## 7. Call to Action")
    lines.append("")
    lines.append(
        "**Approve a quarterly European Economic Convergence Review.** Set a measurable target: "
        "halve the gap between the best- and worst-performing economies within 24 months. "
        "Task the data team with refreshing this dataset monthly and this report quarterly, "
        "and route the next edition to the executive committee with a one-page decision brief."
    )
    lines.append("")

    # ---- appendix -------------------------------------------------------------
    lines.append("---")
    lines.append("")
    lines.append("## Appendix A — Source Files")
    lines.append("")
    for f in files:
        status = f"{len(per_file[f])} records" if f in per_file else "no numeric records parsed"
        lines.append(f"- `{f}` — {status}")
    if skipped:
        lines.append("")
        lines.append("Files with no parseable records: " + ", ".join(f"`{f}`" for f in skipped))
    lines.append("")
    lines.append("## Appendix B — Parsed Data (first 120 records)")
    lines.append("")
    lines.append(records_table(all_records))
    lines.append("")
    lines.append("## Method & Caveats")
    lines.append("")
    lines.append(
        "- Indicators were parsed from CSV/TSV, JSON, Markdown tables, and key:value text; "
        "non-numeric cells were preserved as labels."
    )
    lines.append(
        "- Averages shown are simple arithmetic means across the records available in the workspace "
        "dataset; they are not Eurostat-official aggregates unless the source data says so."
    )
    lines.append(
        "- ASCII bars use a relative scale within each chart; zero is not necessarily the baseline."
    )
    lines.append(
        "- Insights describe observed patterns; correlation is not causation."
    )
    lines.append("")

    return "\n".join(lines), facts


# --------------------------------------------------------------------------
# Main
# --------------------------------------------------------------------------

def main():
    files = discover_files()
    per_file = {}
    skipped = []
    for path in files:
        recs = parse_file(path)
        if recs:
            per_file[path] = recs
        else:
            skipped.append(path)

    all_records = [rec for recs in per_file.values() for rec in recs]

    report, facts = build_report(per_file, all_records, files, skipped)

    with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
        f.write(report)

    # Console summary (verifiable in tool output)
    print("=" * 72)
    print("DATA STORYTELLING REPORT — BUILD SUMMARY")
    print("=" * 72)
    print(f"Workspace root : {ROOT}")
    print(f"Files found    : {len(files)}")
    for p in files:
        print(f"  - {os.path.relpath(p, ROOT)}"
              + (f"  [{len(per_file[p])} records]" if p in per_file else "  [no numeric records]"))
    print(f"Records parsed : {len(all_records)}")
    print(f"Primary metric : {facts.get('primary')}")
    print(f"Entity column  : {facts.get('entity_col')}")
    print(f"Time column    : {facts.get('time_col')}")
    if facts.get("best"):
        print(f"Best performer : {facts['best'][0]} = {fmt(facts['best'][1])}")
        print(f"Worst performer: {facts['worst'][0]} = {fmt(facts['worst'][1])}")
    if facts.get("trend_last"):
        print(f"Trend          : {fmt_year(facts['trend_first'][0])} {fmt(facts['trend_first'][1])}"
              f" -> {fmt_year(facts['trend_last'][0])} {fmt(facts['trend_last'][1])}"
              f" ({fmt(facts.get('trend_pct'))}%)")
    print(f"Report written : {OUTPUT_PATH}")
    print("=" * 72)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Task-scoped helper: build a data storytelling report from the European economic
performance data found in the workspace directory.

Steps:
  1. Discover candidate data files (CSV/TSV/JSON) in this directory tree.
  2. Load each file with heuristics (wide or long formats).
  3. Compute key economic summary metrics per country / per year.
  4. Emit a Markdown report following the data-storytelling skill structure
     (Hook -> Context -> Discovery -> Insight -> Recommendation -> Call to Action).
"""

import csv
import io
import json
import math
import os
import statistics
import sys

WORKSPACE = os.path.dirname(os.path.abspath(__file__))
REPORT_PATH = os.path.join(WORKSPACE, "european_economic_performance_story.md")
LOG = []


def log(msg):
    LOG.append(str(msg))
    print(str(msg), flush=True)


# ----------------------------------------------------------------------------
# Discovery
# ----------------------------------------------------------------------------

DATA_EXTS = {".csv", ".tsv", ".txt", ".json", ".data", ".dat"}


def discover_files():
    found = []
    for root, _dirs, files in os.walk(WORKSPACE):
        for name in sorted(files):
            ext = os.path.splitext(name)[1].lower()
            if ext in DATA_EXTS:
                found.append(os.path.join(root, name))
    return found


# ----------------------------------------------------------------------------
# Parsing
# ----------------------------------------------------------------------------

def sniff_delimiter(sample):
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
        return dialect.delimiter
    except Exception:
        return ","


def parse_csv(path):
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        sample = fh.read(8192)
    delimiter = sniff_delimiter(sample)
    rows = []
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        reader = csv.reader(fh, delimiter=delimiter)
        for row in reader:
            if row and any(cell.strip() for cell in row):
                rows.append([c.strip() for c in row])
    if not rows:
        return None
    return rows


def parse_json(path):
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        return json.load(fh)


def flatten_json(obj, prefix=""):
    """Yield (key_path, value) leaves from a JSON object."""
    out = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            key = f"{prefix}.{k}" if prefix else str(k)
            out.extend(flatten_json(v, key))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            key = f"{prefix}[{i}]"
            out.extend(flatten_json(v, key))
    else:
        out.append((prefix, obj))
    return out


# ----------------------------------------------------------------------------
# Normalisation into records: dicts with (country, year, metric, value)
# ----------------------------------------------------------------------------

COUNTRY_HINTS = [
    "country", "nation", "member", "state", "geo", "territory", "economy",
    "country_name", "geo_name", "reporting country", "country/territory",
]
YEAR_HINTS = ["year", "date", "period", "time", "obs_time", "observation time",
              "year(s)", "ref_year", "ref period"]
METRIC_HINTS = ["metric", "indicator", "variable", "series", "measure", "item",
                "statistic", "subject", "category"]
VALUE_HINTS = ["value", "amount", "rate", "pct", "%", "percentage", "index",
               "observation value", "obs_value"]


def is_number(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, (int, float)):
        return True
    try:
        float(str(v).replace(",", "").replace("%", "").strip())
        return True
    except Exception:
        return False


def to_float(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(str(v).replace(",", "").replace("%", "").strip())
    except Exception:
        return None


def find_header_idx(rows, hints):
    for i, row in enumerate(rows[:8]):
        lowered = [str(c).strip().lower() for c in row]
        for h in hints:
            if any(h in c for c in lowered):
                return i
    return None


def normalize_csv(rows):
    """Return list of records (dict) or None."""
    header_idx = find_header_idx(rows, COUNTRY_HINTS + YEAR_HINTS + METRIC_HINTS + VALUE_HINTS)
    if header_idx is None:
        return None
    header = [str(c).strip().lower() for c in rows[header_idx]]
    body = rows[header_idx + 1:]

    records = []
    col_c = None
    col_y = None
    col_m = None
    col_v = None
    for i, h in enumerate(header):
        hl = h.lower()
        if col_c is None and any(x in hl for x in COUNTRY_HINTS):
            col_c = i
        elif col_y is None and any(x in hl for x in YEAR_HINTS):
            col_y = i
        elif col_m is None and any(x in hl for x in METRIC_HINTS):
            col_m = i
        elif col_v is None and any(x in hl for x in VALUE_HINTS):
            col_v = i

    # Long format: has country + year + metric + value columns.
    if col_c is not None and col_y is not None and col_m is not None and col_v is not None:
        for row in body:
            if len(row) <= max(col_c, col_y, col_m, col_v):
                continue
            val = to_float(row[col_v])
            if val is None:
                continue
            records.append({
                "country": row[col_c],
                "year": str(row[col_y]),
                "metric": row[col_m],
                "value": val,
            })
        return records if records else None

    # Wide format: country rows, metric columns, optional year column.
    if col_c is not None and col_y is not None:
        year = str(body[0][col_y]) if body and len(body[0]) > col_y else "?"
        for row in body:
            if len(row) <= col_c:
                continue
            country = row[col_c]
            for i, h in enumerate(header):
                if i == col_c or i == col_y:
                    continue
                if i < len(row):
                    val = to_float(row[i])
                    if val is not None:
                        records.append({
                            "country": country,
                            "year": year,
                            "metric": h,
                            "value": val,
                        })
        return records if records else None

    if col_c is not None:
        # Country rows with numeric columns; column headers are metrics.
        for row in body:
            if len(row) <= col_c:
                continue
            country = row[col_c]
            for i, h in enumerate(header):
                if i == col_c:
                    continue
                if i < len(row):
                    val = to_float(row[i])
                    if val is not None:
                        records.append({
                            "country": country,
                            "year": "?",
                            "metric": h,
                            "value": val,
                        })
        return records if records else None

    return None


def normalize_json(obj):
    leaves = flatten_json(obj)
    records = []
    for key, val in leaves:
        if not is_number(val):
            continue
        kl = key.lower()
        parts = [p for p in key.replace("[", ".").replace("]", "").split(".") if p]
        country = None
        year = None
        metric = key
        for p in parts:
            pl = p.lower()
            if country is None and any(x in pl for x in COUNTRY_HINTS):
                country = p
            if year is None and any(x in pl for x in YEAR_HINTS):
                year = p
        if country is None and parts:
            # Fallback: first segment could be a country name
            first = parts[0]
            if not any(x in first.lower() for x in ["value", "year", "total", "data", "report"]):
                country = first
        records.append({
            "country": country if country else "All",
            "year": year if year else "?",
            "metric": metric,
            "value": float(val),
        })
    return records if records else None


def load_all():
    records = []
    sources = []
    for path in discover_files():
        try:
            ext = os.path.splitext(path)[1].lower()
            if ext == ".json":
                obj = parse_json(path)
                recs = normalize_json(obj)
            else:
                rows = parse_csv(path)
                recs = normalize_csv(rows) if rows else None
            if recs:
                records.extend(recs)
                sources.append(os.path.relpath(path, WORKSPACE))
                log(f"Loaded {len(recs)} records from {os.path.relpath(path, WORKSPACE)}")
            else:
                log(f"Skipped {os.path.relpath(path, WORKSPACE)} (no tabular structure detected)")
        except Exception as exc:
            log(f"Could not parse {os.path.relpath(path, WORKSPACE)}: {exc}")
    return records, sources


# ----------------------------------------------------------------------------
# Analysis helpers
# ----------------------------------------------------------------------------

def group_records(records):
    """Return {(country, metric): {year: value}}."""
    groups = {}
    for r in records:
        key = (r["country"], r["metric"])
        groups.setdefault(key, {})[r["year"]] = r["value"]
    return groups


def metric_aliases(metric):
    m = str(metric).lower()
    if any(x in m for x in ["gdp", "gross domestic product", "growth rate", "real gdp"]):
        return "gdp_growth"
    if any(x in m for x in ["unemploy", "jobless"]):
        return "unemployment"
    if any(x in m for x in ["inflation", "hicp", "price", "cpi"]):
        return "inflation"
    if any(x in m for x in ["debt", "deficit", "fiscal", "public finance", "government balance"]):
        return "fiscal"
    if any(x in m for x in ["trade", "export", "import", "balance of payments", "current account"]):
        return "trade"
    if any(x in m for x in ["invest", "capital formation", "capex"]):
        return "investment"
    if any(x in m for x in ["productivity", "output per", "labour", "labor", "employment"]):
        return "labour"
    if any(x in m for x in ["population", "demograph"]):
        return "demography"
    return "other"


def summarize(records):
    summary = {
        "total_records": len(records),
        "countries": sorted({r["country"] for r in records}),
        "years": sorted({r["year"] for r in records if r["year"] != "?"}),
        "metrics": {},
    }
    for r in records:
        cat = metric_aliases(r["metric"])
        summary["metrics"].setdefault(cat, []).append(r)
    return summary


def numeric_years(years):
    out = []
    for y in years:
        try:
            out.append(int(str(y)[:4]))
        except Exception:
            continue
    return sorted(set(out))


def growth_series(values):
    """Return list of (year, value) sorted by year with numeric coercion."""
    out = []
    for k, v in values.items():
        try:
            out.append((int(str(k)[:4]), float(v)))
        except Exception:
            continue
    out.sort()
    return out


def pct_change(first, last):
    if first in (None, 0) or last is None:
        return None
    try:
        return (float(last) - float(first)) / abs(float(first)) * 100.0
    except Exception:
        return None


def fmt(v, digits=2):
    if v is None:
        return "n/a"
    if isinstance(v, float):
        if abs(v) >= 1000:
            return f"{v:,.0f}"
        return f"{v:.{digits}f}"
    return str(v)


def pct(v):
    if v is None:
        return "n/a"
    return f"{v:+.2f}%"


# ----------------------------------------------------------------------------
# Report generation (data storytelling structure per the skill)
# ----------------------------------------------------------------------------

def build_section_baseline(summary, groups):
    countries = summary["countries"]
    years = summary["years"]
    nyears = numeric_years(years)
    lines = []
    lines.append(f"### Context at a glance\n")
    lines.append(f"- **Data sources discovered:** {len(summary['total_records'] and summary['total_records'] or 0)} records across "
                 f"{len(countries)} economies and {len(nyears) or 'multiple'} time periods (years found: {', '.join(map(str, nyears[:8]))}{'…' if len(nyears) > 8 else ''}).")
    lines.append(f"- **Countries / economies covered:** {', '.join(countries[:24])}{' …' if len(countries) > 24 else ''}.")
    lines.append(f"- **Metric families detected:** {', '.join(k for k in summary['metrics'] if summary['metrics'][k])}.\n")
    lines.append("**Latest observed values by country (where available):**\n")
    lines.append("| Economy | Latest GDP growth % | Latest unemployment % | Latest inflation % |")
    lines.append("|---|---|---|---|")
    latest = {}
    for cat in ["gdp_growth", "unemployment", "inflation"]:
        latest[cat] = {}
        for r in summary["metrics"].get(cat, []):
            try:
                yr = int(str(r["year"])[:4])
            except Exception:
                continue
            prev = latest[cat].get(r["country"], (-10**9, None))
            if yr > prev[0]:
                latest[cat][r["country"]] = (yr, r["value"])
    for c in countries:
        g = latest["gdp_growth"].get(c, (None, None))[1]
        u = latest["unemployment"].get(c, (None, None))[1]
        i = latest["inflation"].get(c, (None, None))[1]
        lines.append(f"| {c} | {fmt(g)} | {fmt(u)} | {fmt(i)} |")
    return "\n".join(lines)


def build_section_trends(summary, groups):
    lines = []
    lines.append("### The trend story\n")
    # For each country+metric group with >=2 numeric years, compute change.
    rows = []
    for (country, metric), values in groups.items():
        series = growth_series(values)
        if len(series) < 2:
            continue
        cat = metric_aliases(metric)
        first = series[0][1]
        last = series[-1][1]
        chg = pct_change(first, last)
        rows.append((cat, country, metric, series[0][0], series[-1][0], first, last, chg))
    if rows:
        lines.append("**Change between earliest and latest observed period (largest moves first):**\n")
        lines.append("| Metric family | Economy | Indicator | Period span | Change % | Direction |")
        lines.append("|---|---|---|---|---|---|")
        rows.sort(key=lambda r: -(r[7] if r[7] is not None else -10**9))
        for cat, country, metric, y1, y2, v1, v2, chg in rows[:20]:
            direction = "▲" if (chg or 0) > 0 else ("▼" if (chg or 0) < 0 else "→")
            lines.append(f"| {cat} | {country} | {metric} | {y1}→{y2} | {pct(chg)} | {direction} |")
    else:
        lines.append("Not enough multi-year series were detected to compute trends.\n")
    return "\n".join(lines)


def build_section_insights(summary, groups):
    lines = []
    lines.append("### Key insights\n")
    bullets = []

    # Insight 1: strongest growth vs weakest.
    growth_rows = []
    for (country, metric), values in groups.items():
        if metric_aliases(metric) != "gdp_growth":
            continue
        series = growth_series(values)
        if len(series) >= 2:
            chg = pct_change(series[0][1], series[-1][1])
            growth_rows.append((country, series[0][0], series[-1][0], series[0][1], series[-1][1], chg))
    if growth_rows:
        growth_rows.sort(key=lambda r: -(r[5] if r[5] is not None else -10**9))
        top = growth_rows[0]
        bottom = growth_rows[-1]
        bullets.append(
            f"GDP growth leaders and laggards: the strongest mover was **{top[0]}** "
            f"({pct(top[5])} between {top[1]} and {top[2]}), while **{bottom[0]}** moved {pct(bottom[5])} "
            f"over the same kind of window — a spread of {fmt((top[5] or 0) - (bottom[5] or 0))} percentage points."
        )

    # Insight 2: unemployment dispersion (labour-market divide).
    unemp_rows = []
    for (country, metric), values in groups.items():
        if metric_aliases(metric) != "unemployment":
            continue
        series = growth_series(values)
        if series:
            unemp_rows.append((country, series[-1][0], series[-1][1]))
    if unemp_rows:
        unemp_rows.sort(key=lambda r: r[2])
        best = unemp_rows[0]
        worst = unemp_rows[-1]
        spread = worst[2] - best[2]
        bullets.append(
            f"Labour-market divide: unemployment is lowest in **{best[0]}** ({fmt(best[2])}%) and highest in "
            f"**{worst[0]}** ({fmt(worst[2])}%) — a {fmt(spread)}-point gap, pointing to uneven recovery across the continent."
        )

    # Insight 3: inflation / price pressure.
    inf_rows = []
    for (country, metric), values in groups.items():
        if metric_aliases(metric) != "inflation":
            continue
        series = growth_series(values)
        if series:
            inf_rows.append((country, series[-1][0], series[-1][1]))
    if inf_rows:
        inf_rows.sort(key=lambda r: r[2], reverse=True)
        hottest = inf_rows[0]
        bullets.append(
            f"Price pressures: **{hottest[0]}** posted the highest latest inflation reading "
            f"({fmt(hottest[2])}%, {hottest[1]}), a reminder that disinflation is unevenly distributed."
        )

    # Insight 4: convergence/divergence across countries for any shared metric.
    if len(countries := summary["countries"]) >= 3:
        for cat in ["gdp_growth", "unemployment", "inflation"]:
            vals = []
            for (country, metric), values in groups.items():
                if metric_aliases(metric) != cat:
                    continue
                series = growth_series(values)
                if series:
                    vals.append(series[-1][1])
            if len(vals) >= 3:
                spread = max(vals) - min(vals)
                bullets.append(
                    f"Dispersion check ({cat}): latest values range from {fmt(min(vals))} to {fmt(max(vals))} "
                    f"(spread {fmt(spread)} points) — {'wide divergence, so headline averages hide real winners and losers' if spread > 10 else 'a relatively contained spread, suggesting a synchronised cycle'}."
                )

    if not bullets:
        bullets.append("The available series were too sparse for statistically robust narratives; the report below still flags the patterns the data does support.")
    for b in bullets:
        lines.append(f"- {b}")
    return "\n".join(lines)


def build_section_recommendations(summary):
    lines = []
    lines.append("### What the story implies\n")
    lines.append("1. **Read the averages with caution.** European headline indicators smooth over a wide country-level spread — decisions and messaging should be built on country and sector detail, not the EU-wide mean.")
    lines.append("2. **Watch the laggards first.** Economies with the weakest growth and the highest unemployment in this dataset are where policy attention (structural funds, training, investment incentives) has the highest marginal return.")
    lines.append("3. **Keep monitoring price pressure per economy.** If the top inflation reading keeps diverging from the median, monetary-policy transmission is uneven and risk premia will differ by country.")
    lines.append("4. **Extend the time series.** A stronger narrative needs more consecutive years per country; the recommendation is to enrich this dataset with quarterly frequency and sectoral breakdowns before the next review.")
    return "\n".join(lines)


def build_report(summary, groups, sources):
    title = "European Economic Performance: The Story in the Data"
    hook = (
        "**The hook:** Europe's headline recovery numbers look solid — but the underlying data tells a story of "
        "winners and laggards, of widening gaps hidden inside continental averages."
    )
    header = f"""# {title}

> {hook}

---

## 1. The setup — what the data covers

{summary.get("total_records", 0)} data records were found and analysed from the workspace
(source files: {', '.join(sources) if sources else 'none detected'}).

"""

    sections = [
        ("## 2. The context — baseline snapshot", build_section_baseline(summary, groups)),
        ("## 3. Rising action — the trends", build_section_trends(summary, groups)),
        ("## 4. The climax — key insights", build_section_insights(summary, groups)),
        ("## 5. The resolution — recommendations", build_section_recommendations(summary)),
    ]

    footer = f"""
---

## 6. Call to action

- **For leadership:** review the country-level divergences above and decide where the next growth push should land.
- **For analysts:** extend the series with quarterly observations and sectoral splits so next quarter's story can be told with more certainty.
- **For the next report:** re-run this pipeline on the refreshed dataset and track whether the spreads above are narrowing (convergence) or widening (fragmentation).

---

*Generated by the task-scoped data-storytelling helper from the European economic performance data in this directory.*
*Method note: figures are computed directly from the records found; blank cells mean the indicator was not present for that economy in the source data.*
"""
    return header + "\n".join(f"{head}\n\n{body}\n" for head, body in sections) + footer


# ----------------------------------------------------------------------------
# Main
# ----------------------------------------------------------------------------

def main():
    log(f"Workspace: {WORKSPACE}")
    log("Discovering data files…")
    files = discover_files()
    if not files:
        log("ERROR: no candidate data files found in workspace.")
        return 2
    for f in files:
        log(f"  found: {os.path.relpath(f, WORKSPACE)}")

    records, sources = load_all()
    if not records:
        log("ERROR: no numeric economic records could be extracted.")
        return 3

    summary = summarize(records)
    groups = group_records(records)

    log(f"Summary: {len(records)} records, {len(summary['countries'])} countries, "
        f"{len(summary['years'])} distinct year labels, "
        f"{len({m for (_c, m) in groups})} distinct indicator labels.")

    report = build_report(summary, groups, sources)
    with open(REPORT_PATH, "w", encoding="utf-8") as fh:
        fh.write(report)
    log(f"Report written to {REPORT_PATH} ({len(report)} chars).")

    # Sanity re-read to confirm the artifact is valid UTF-8 and complete.
    with open(REPORT_PATH, "r", encoding="utf-8") as fh:
        verify = fh.read()
    if verify == report:
        log("Verification OK: report round-trip matches.")
    else:
        log("Verification WARNING: round-trip mismatch.")
        return 4

    print("\n----- REPORT PREVIEW (first 3000 chars) -----")
    print(report[:3000])
    return 0


if __name__ == "__main__":
    sys.exit(main())

